<script setup>
import { computed, onMounted, ref } from 'vue';
import DataTable from 'primevue/datatable';
import Column from 'primevue/column';
import Paginator from 'primevue/paginator';
import Dropdown from 'primevue/dropdown';
import InputText from 'primevue/inputtext';
import apiClient from '../services/apiClient';
import { createLogger, logException } from '../utils/logger';

const logger = createLogger('AdminUsers');
const users = ref([]); const loading = ref(false); const search = ref(''); const role = ref(null); const verificationStatus = ref(null); const accountStatus = ref(null); const error = ref(''); const meta = ref({ current_page: 1, last_page: 1, total: 0, per_page: 10 });
const roleOptions = [{ label: 'همه نقش‌ها', value: null }, { label: 'سوپر ادمین', value: 'super_admin' }, { label: 'مدیر سامانه', value: 'admin' }, { label: 'مدیر مالی', value: 'financial_manager' }, { label: 'اپراتور', value: 'operator' }, { label: 'حسابدار / ناظر', value: 'auditor' }, { label: 'کاربر عادی', value: 'buyer' }];
const verificationOptions = [{ label: 'همه وضعیت‌ها', value: null }, { label: 'تایید شده', value: 'verified' }, { label: 'در انتظار بررسی', value: 'pending' }, { label: 'رد شده', value: 'rejected' }];
const accountStatusOptions = [{ label: 'همه کاربران', value: null }, { label: 'فعال', value: 'active' }, { label: 'مسدودشده', value: 'banned' }];
const visibleRange = computed(() => `${users.value.length} کاربر از ${meta.value.total} کاربر`);
async function load(page = 1) { loading.value = true; error.value = ''; try { const { data } = await apiClient.get('/admin/users', { params: { search: search.value || undefined, role: role.value || undefined, kyc_status: verificationStatus.value || undefined, status: accountStatus.value || undefined, page, per_page: 10 } }); users.value = data.data || []; meta.value = data.meta || meta.value; } catch (exception) { error.value = 'دریافت کاربران انجام نشد.'; logger.error('load', 'Admin users failed', logException(exception)); } finally { loading.value = false; } }
async function toggleBan(user) { try { const { data } = await apiClient.patch(`/admin/users/${user.id}/status`, { is_banned: !user.is_banned }); user.is_banned = data.data.is_banned; } catch (exception) { error.value = 'تغییر وضعیت کاربر انجام نشد.'; logger.error('toggleBan', 'User status update failed', logException(exception)); } }
function roleLabel(roleName) { return { super_admin: 'سوپر ادمین', admin: 'مدیر سامانه', financial_manager: 'مدیر مالی', operator: 'اپراتور', auditor: 'حسابرس', buyer: 'کاربر بازار', seller: 'فروشنده' }[roleName] || 'کاربر بازار'; }
function roleClass(roleName) { return ['super_admin', 'admin'].includes(roleName) ? 'role-indigo' : roleName === 'financial_manager' ? 'role-emerald' : roleName === 'operator' ? 'role-sky' : 'role-gray'; }
function verificationClass(user) { return user.is_verified ? 'status-ok' : 'status-wait'; }
function clearFilters() { search.value = ''; role.value = null; verificationStatus.value = null; accountStatus.value = null; load(1); }
onMounted(load);
</script>

<template><section class="ops-page"><header class="ops-page__header"><div><span>مدیریت سامانه / کاربران</span><h1>مدیریت کاربران</h1><p>وضعیت هویت و دسترسی کاربران را مشاهده و کنترل کنید.</p></div></header><p v-if="error" class="ops-error">{{ error }}</p><div class="ops-toolbar" dir="rtl"><div class="filter-heading"><span class="filter-heading__eyebrow"><i class="pi pi-users"></i>مرکز کنترل کاربران</span><strong>فیلتر و جست‌وجوی کاربران</strong></div><div class="smart-search"><label for="users-search">جست‌وجوی هوشمند</label><span class="search-box"><i class="pi pi-search"></i><InputText id="users-search" v-model="search" placeholder="نام، ایمیل یا شماره موبایل" @keyup.enter="load(1)" /></span></div><div class="filter-control"><label for="users-role">نقش کاربری</label><Dropdown id="users-role" v-model="role" :options="roleOptions" optionLabel="label" optionValue="value" class="filter-select" panelClass="users-filter-panel" /></div><div class="filter-control"><label for="users-kyc-status">وضعیت احراز هویت</label><Dropdown id="users-kyc-status" v-model="verificationStatus" :options="verificationOptions" optionLabel="label" optionValue="value" class="filter-select" panelClass="users-filter-panel" /></div><div class="filter-control"><label for="users-account-status">وضعیت دسترسی</label><Dropdown id="users-account-status" v-model="accountStatus" :options="accountStatusOptions" optionLabel="label" optionValue="value" class="filter-select" panelClass="users-filter-panel" /></div><button class="filter-clear" type="button" title="پاک‌سازی فیلترها" @click="clearFilters"><i class="pi pi-filter-slash"></i><span>پاک‌سازی</span></button><button class="search-button filter-submit" type="button" @click="load(1)"><i class="pi pi-search"></i>جست‌وجو و اعمال فیلتر</button></div><div class="table-card"><DataTable :value="users" dataKey="id" :loading="loading" stripedRows responsiveLayout="scroll"><Column header="کاربر"><template #body="slotProps"><div class="user-cell"><span class="avatar">{{ (slotProps.data.name || 'ک').slice(0, 1) }}</span><div><strong>{{ slotProps.data.name || 'بدون نام' }}</strong><small>{{ slotProps.data.mobile }}</small></div></div></template></Column><Column header="ایمیل"><template #body="slotProps"><span class="email-cell">{{ slotProps.data.email || '-' }}</span></template></Column><Column header="نقش‌ها"><template #body="slotProps"><div class="role-list"><span v-for="userRole in (slotProps.data.roles?.length ? slotProps.data.roles : [{ name: 'buyer' }])" :key="userRole.name" class="role-badge" :class="roleClass(userRole.name)">{{ roleLabel(userRole.name) }}</span></div></template></Column><Column header="احراز هویت"><template #body="slotProps"><span class="status-badge" :class="verificationClass(slotProps.data)"><i :class="slotProps.data.is_verified ? 'pi pi-check-circle' : 'pi pi-clock'"></i>{{ slotProps.data.is_verified ? 'تایید شده' : 'در انتظار' }}</span></template></Column><Column header="عملیات"><template #body="slotProps"><div class="action-list"><button class="icon-action icon-action--danger" type="button" :title="slotProps.data.is_banned ? 'آزادسازی کاربر' : 'مسدودسازی کاربر'" @click="toggleBan(slotProps.data)"><i :class="slotProps.data.is_banned ? 'pi pi-unlock' : 'pi pi-ban'"></i></button><button class="icon-action" type="button" title="مشاهده جزئیات"><i class="pi pi-eye"></i></button></div></template></Column><template #empty><div class="table-empty"><i class="pi pi-users"></i><p>کاربری با این فیلترها پیدا نشد.</p></div></template></DataTable><footer class="table-footer"><span>نمایش {{ visibleRange }}</span><Paginator :first="(meta.current_page - 1) * meta.per_page" :rows="meta.per_page" :totalRecords="meta.total" :rowsPerPageOptions="[10]" @page="load($event.page + 1)" /></footer></div></section></template>

<style scoped>
.ops-page { max-width: 1280px; margin: 0 auto; }.ops-page__header { margin-bottom: 25px; }.ops-page__header span { color: #a62626; font-size: 10px; }.ops-page h1 { margin: 7px 0 4px; font-size: 26px; }.ops-page__header p { margin: 0; color: #64748b; font-size: 12px; }.ops-toolbar { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 16px; }.search-box { display: flex; width: 288px; align-items: center; gap: 9px; padding: 0 14px; border: 1px solid #d1d5db; border-radius: 12px; background: #fff; color: #94a3b8; }.search-box:focus-within { border-color: #a62626; box-shadow: 0 0 0 3px #fee2e2; }.search-box input { width: 100%; padding: 10px 0; border: 0; outline: 0; color: #374151; font: inherit; font-size: 12px; }.filter-select { min-width: 145px; border-radius: 12px; border-color: #d1d5db; }.search-button { padding: 10px 14px; border: 0; border-radius: 10px; background: #a62626; color: #fff; cursor: pointer; font: inherit; font-size: 11px; }.search-button i { margin-left: 6px; }.table-card { overflow: hidden; border: 1px solid rgba(229, 231, 235, .8); border-radius: 16px; background: #fff; box-shadow: 0 2px 8px #0f172a0a; }.table-card :deep(.p-datatable) { font-size: 12px; }.table-card :deep(.p-datatable-thead > tr > th) { padding: 14px 16px; border-bottom: 1px solid #e5e7eb; background: rgba(249, 250, 251, .9); color: #374151; font-size: 11px; font-weight: 700; text-align: right; }.table-card :deep(.p-datatable-tbody > tr) { transition: background-color .18s; }.table-card :deep(.p-datatable-tbody > tr:hover) { background: rgba(248, 250, 252, .8); }.table-card :deep(.p-datatable-tbody > tr > td) { padding: 14px 16px; border-bottom: 1px solid #f3f4f6; color: #374151; }.user-cell { display: flex; align-items: center; gap: 11px; }.user-cell strong, .user-cell small { display: block; }.user-cell strong { color: #1f2937; font-size: 12px; }.user-cell small { margin-top: 4px; color: #9ca3af; font-family: ui-monospace, monospace; font-size: 10px; direction: ltr; text-align: right; }.avatar { display: grid; width: 34px; height: 34px; flex: 0 0 34px; place-items: center; border-radius: 50%; background: #fee2e2; color: #a62626; font-weight: 800; }.email-cell { color: #6b7280; direction: ltr; font-size: 11px; }.role-list { display: flex; flex-wrap: wrap; gap: 5px; }.role-badge, .status-badge { display: inline-flex; align-items: center; gap: 4px; padding: 4px 8px; border: 1px solid transparent; border-radius: 999px; font-size: 9px; font-weight: 700; }.role-indigo { border-color: #e0e7ff; background: #eef2ff; color: #4338ca; }.role-emerald { background: #ecfdf5; color: #047857; }.role-sky { background: #f0f9ff; color: #0369a1; }.role-gray { background: #f3f4f6; color: #6b7280; }.status-ok { background: #ecfdf5; color: #047857; }.status-wait { background: #fffbeb; color: #b45309; }.action-list { display: flex; gap: 4px; }.icon-action { display: grid; width: 31px; height: 31px; place-items: center; border: 0; border-radius: 8px; background: transparent; color: #64748b; cursor: pointer; }.icon-action:hover { background: #f1f5f9; color: #334155; }.icon-action--danger { color: #dc2626; }.icon-action--danger:hover { background: #fef2f2; }.table-empty { padding: 35px 10px; color: #9ca3af; text-align: center; }.table-empty i { color: #d1d5db; font-size: 30px; }.table-empty p { margin: 8px 0 0; font-size: 11px; }.table-footer { display: flex; align-items: center; justify-content: space-between; padding: 8px 16px 8px 10px; color: #6b7280; font-size: 10px; }.table-footer :deep(.p-paginator) { justify-content: flex-start; padding: 4px 0; direction: rtl; }.table-footer :deep(.p-paginator-page.p-highlight) { border-color: #a62626; background: #a62626; color: #fff; }.table-footer :deep(.p-paginator-page), .table-footer :deep(.p-paginator-prev), .table-footer :deep(.p-paginator-next) { min-width: 30px; height: 30px; border-radius: 8px; color: #64748b; }.ops-error { padding: 10px; background: #fef2f2; color: #b91c1c; font-size: 11px; }
.ops-toolbar { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 12px; margin-bottom: 24px; padding: 16px; border: 1px solid #e2e8f0; border-radius: 16px; background: #fff; box-shadow: 0 4px 14px rgba(15, 23, 42, .06); }.filter-heading { display: grid; min-width: 150px; gap: 4px; margin-left: auto; color: #0f172a; }.filter-heading__eyebrow { display: flex; align-items: center; gap: 6px; color: #a62626; font-size: 10px; font-weight: 800; }.filter-heading strong { font-size: 13px; }.filter-control, .smart-search { display: grid; min-width: 170px; gap: 6px; }.filter-control label, .smart-search label { color: #64748b; font-size: 10px; font-weight: 800; }.filter-select { width: 100%; min-height: 42px; border: 1px solid #cbd5e1; border-radius: 12px; background: #fff; box-shadow: 0 1px 2px rgba(15, 23, 42, .05); }.filter-select :deep(.p-select-label), .filter-select :deep(.p-dropdown-label) { padding: 11px 14px; color: #334155; font-size: 11px; }.filter-select :deep(.p-select-dropdown), .filter-select :deep(.p-dropdown-trigger) { width: 2.5rem; color: #64748b; }.filter-select:focus-within { border-color: #a62626; box-shadow: 0 0 0 3px #fee2e2; }.smart-search { min-width: 270px; flex: 1 1 280px; }.smart-search .search-box { display: flex; width: 100%; align-items: center; gap: 8px; min-height: 42px; padding: 0 13px; border: 1px solid #cbd5e1; border-radius: 12px; background: #fff; color: #94a3b8; box-shadow: 0 1px 2px rgba(15, 23, 42, .05); }.smart-search .search-box:focus-within { border-color: #a62626; box-shadow: 0 0 0 3px #fee2e2; }.smart-search .search-box :deep(.p-inputtext) { width: 100%; padding: 10px 0; border: 0; outline: 0; box-shadow: none; font: inherit; font-size: 11px; }.filter-clear, .filter-submit { display: inline-flex; min-height: 42px; align-items: center; justify-content: center; gap: 7px; padding: 10px 14px; border-radius: 12px; cursor: pointer; font: inherit; font-size: 10px; font-weight: 800; white-space: nowrap; }.filter-clear { border: 1px solid #cbd5e1; background: #f8fafc; color: #475569; }.filter-clear:hover { border-color: #a62626; background: #fff1f2; color: #a62626; }.filter-submit { padding: 10px 18px; border: 1px solid #a62626; background: #a62626; color: #fff; }.filter-submit:hover { background: #861f1f; }@media (max-width: 900px) { .filter-heading { width: 100%; margin-left: 0; }.filter-control { flex: 1 1 180px; }.smart-search { flex-basis: 100%; } }@media (max-width: 560px) { .ops-toolbar { align-items: stretch; padding: 13px; }.filter-control, .smart-search { width: 100%; min-width: 0; flex-basis: 100%; }.filter-clear, .filter-submit { width: 100%; } }
